// ===== Match Catalog =====
const cat = $input.all().map(i => i.json).filter(x => x.sku);

function getNode(name) {
  const variants = [name, name + ' ', ' ' + name, name.replace(/ /g, '\u00A0')];
  for (const n of variants) {
    try {
      const it = $(n).first();
      if (it) return it.json;
    } catch (e) {}
  }
  throw new Error('Node not found: ' + name);
}

const msg  = getNode('Normalize Message');
const aiIn = getNode('AI Read Request');

function parseAI(raw) {
  if (raw.items || raw.medicines) return raw;
  let t = '';
  if (raw.candidates && raw.candidates[0]) {
    t = raw.candidates[0].content.parts[0].text;
  } else if (raw.choices && raw.choices[0]) {
    t = raw.choices[0].message.content;
  } else {
    t = raw.output || raw.text || '';
  }
  if (typeof t !== 'string') return t || {};
  t = t.replace(/`{3}(?:json)?/g, '').trim();
  try { return JSON.parse(t); } catch (e) { return { readable: false, items: [] }; }
}

const r = parseAI(aiIn);
r.is_prescription = (r.is_prescription !== undefined) ? r.is_prescription : (msg.type === 'image');
r.readable = r.readable !== false;

const norm = s => String(s || '').toLowerCase()
  .replace(/[\u064B-\u0652]/g, '')
  .replace(/[^a-z0-9\u0600-\u06FF]/g, '');

function lev(a, b) {
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  let prev = [];
  for (let j = 0; j <= n; j++) prev.push(j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[n];
}

// الأدوية المطلوبة: من الـ AI (items أو medicines)
let items = r.items || r.medicines || [];

// احتياطي: لو الـ AI رجّع فاضي ورسالة نص، ناخد الأسماء من نص العميل
if (items.length === 0 && msg.type === 'text' && msg.text) {
  items = msg.text.split(/[\n,،+]+/)
    .map(s => ({ name: s.trim(), qty: 1 }))
    .filter(x => x.name);
}

const lines = [];
const unclear = (r.unclear || []).slice();

for (const m of items) {
  const q = norm(m.name);
  if (!q) { if (String(m.name || '').trim()) unclear.push(String(m.name).trim()); continue; }  // "?" -> pharmacist
  const qty = Math.max(1, Math.round(Number(m.qty) || 1));

  let best = null;
  for (const p of cat) {
    const d = Math.min(lev(q, norm(p.name)), lev(q, norm(p.active_ingredient)));
    const sPen  = (m.strength && norm(m.strength) !== norm(p.strength)) ? 0.5 : 0;
    const stPen = (Number(p.stock) >= qty) ? 0 : 0.1;
    const score = d + sPen + stPen;
    if (!best || score < best.score) best = { p: p, d: d, score: score };
  }

  const limit = Math.max(1, Math.floor(q.length * 0.3));
  if (!best || best.d > limit) { unclear.push(m.name); continue; }

  const p = best.p;
  const inStock = Number(p.stock) >= qty;
  const alts = cat.filter(x => x.sku !== p.sku
    && x.active_ingredient === p.active_ingredient
    && x.strength === p.strength
    && Number(x.stock) >= qty);

  let alt = '';
  if (!inStock && alts[0]) {
    alt = alts[0].name + ' ' + alts[0].strength + ' (' + alts[0].sku + ', ' + alts[0].price_egp + ' EGP)';
  }

  lines.push({
    sku: p.sku,
    name: p.name + ' ' + p.strength,
    qty: qty,
    price: Number(p.price_egp),
    in_stock: inStock,
    controlled: p.controlled === 'yes',
    fuzzy: best.d > 0,
    alternative: alt
  });
}

const needsPharmacist = !!(r.is_prescription || (msg.type === 'audio' && !(r.confidence === 'high' || msg.confidence === 'high')) || !r.readable || unclear.length > 0
  || lines.some(l => l.controlled || !l.in_stock || l.fuzzy));

const now = new Date();
const ymd = now.toISOString().slice(2, 10).replace(/-/g, '');
const rnd = Math.random().toString(36).slice(2, 6).toUpperCase();

let total = 0;
for (const l of lines) { if (l.in_stock) total += l.price * l.qty; }

return [{
  json: {
    customer_id:   msg.customer_id,
    customer_name: msg.customer_name,
    wa_phone_id:   msg.wa_phone_id,
    type:          msg.type,
    text:          msg.text || '',
    media_id:      msg.media_id || '',
    mime:          msg.mime || '',
    group:         'R-' + ymd + '-' + rnd,
    lines: lines,
    unclear: unclear,
    readable: r.readable,
    transcript:    String(r.transcript || ''),
    confidence:    String(r.confidence || msg.confidence || ''),
    needsPharmacist: needsPharmacist,
    nothing: lines.length === 0 && unclear.length === 0,
    total: total
  }
}];

// ===== One Row per Medicine =====
const j = $input.first().json;

const EXPIRY_MIN = 120; // مدة الحجز بالدقايق
const status = j.needsPharmacist ? 'pending_pharmacist' : 'reserved';
const exp = $now.setZone('Africa/Cairo').plus({ minutes: EXPIRY_MIN }).toFormat('yyyy-MM-dd HH:mm');

const base = {
  customer_id: j.customer_id,
  wa_phone_id: j.wa_phone_id,
  customer_name: j.customer_name
};

const rows = (j.lines || []).map(l => ({
  ...base,
  sku: l.sku,
  name: l.name,
  qty: l.qty,
  total_egp: l.qty * l.price,
  status: status,
  expires_at: status === 'reserved' ? exp : '',
  note: [
    l.controlled ? 'controlled' : '',
    l.in_stock ? '' : 'out of stock',
    l.alternative ? 'alt: ' + l.alternative : '',
    l.fuzzy ? 'fuzzy match' : ''
  ].filter(Boolean).join('; ')
}));

for (const u of (j.unclear || [])) {
  rows.push({
    ...base,
    sku: '',
    name: String(u),
    qty: 1,
    total_egp: 0,
    status: 'pending_pharmacist',
    expires_at: '',
    note: 'not in catalog or unreadable'
  });
}

return rows.map((r, k) => ({ json: { res_id: j.group + '-' + (k + 1), ...r } }));

// Take Stock Now: يخصم بس من الحجوزات اللي اتسجّلت reserved، ولا ينزل تحت الصفر
const rows = $input.all().map(i => i.json)
  .filter(r => r.status === 'reserved' && r.sku);

const cat = Object.fromEntries(
  $('Read Catalog').all().map(i => [i.json.sku, Number(i.json.stock)])
);

const touched = [];
for (const r of rows) {
  if (cat[r.sku] === undefined) continue;
  cat[r.sku] -= Number(r.qty) || 0;
  if (cat[r.sku] < 0) throw new Error('VALIDATION: stock for ' + r.sku + ' would go negative');
  if (touched.indexOf(r.sku) < 0) touched.push(r.sku);
}

return touched.map(sku => ({ json: { sku: sku, stock: cat[sku] } }));

