={{ (() => {
  const m = $('Match Catalog').first().json;
  const R = '\u200F';
  const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const keys = ['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣','7️⃣','8️⃣','9️⃣'];
  const flags = l => [
    !l.in_stock ? '⚠️ مخزون ناقص' : '',
    l.controlled ? '🔒 دواء مراقب' : '',
    l.fuzzy ? '🔍 تطابق تقريبي' : ''
  ].filter(Boolean).join('  ·  ') || '✅ متوفر';
  const items = m.lines.map((l, i) =>
    R + (keys[i] || (i + 1) + '.') + ' <b>' + esc(l.name) + '</b>\n'
    + R + '      الكمية: ' + l.qty + '  ·  💵 ' + (l.qty * l.price) + ' جنيه\n'
    + R + '      ' + flags(l)
    + (l.alternative ? '\n' + R + '      ↳ بديل: ' + esc(l.alternative) : '')
  ).join('\n\n');
  const unclear = (m.unclear || []).length
    ? '\n\n' + R + '❓ <b>غير واضح أو غير موجود:</b>\n' + m.unclear.map(u => R + '      • ' + esc(u)).join('\n')
    : '';
  const total = m.lines.reduce((s, l) => s + l.qty * l.price, 0);
  const high = m.lines.some(l => !l.in_stock || l.controlled);
  const mid = m.type === 'image' || m.type === 'audio' || !m.readable || (m.unclear || []).length > 0 || m.lines.some(l => l.fuzzy);
  const badge = high ? '🔴 أولوية عالية' : (mid ? '🟡 تحتاج مراجعة' : '🟢 عادي');
  const why = [
    m.type === 'image' ? 'روشتة' : '',
    m.type === 'audio' ? 'فويس' : '',
    !m.readable ? 'غير مقروء' : '',
    (m.unclear || []).length ? 'اسم غير واضح' : '',
    m.lines.some(l => l.fuzzy) ? 'تطابق تقريبي' : '',
    m.lines.some(l => l.controlled) ? 'دواء مراقب' : '',
    m.lines.some(l => !l.in_stock) ? 'مخزون ناقص' : ''
  ].filter(Boolean).join('، ');
  const time = $now.setZone('Africa/Cairo').toFormat('HH:mm');
  const bar = '🟦▬▬▬▬▬▬▬▬▬▬▬▬▬🟦';
  return R + bar + '\n'
    + R + '🏥 <b>صيدلية دواء</b>\n'
    + R + '🔔 <b>طلب جديد للمراجعة</b>\n'
    + R + bar + '\n\n'
    + R + badge + '   ·   🕒 ' + time + '\n\n'
    + '<blockquote>'
    + R + '🧾 رقم الطلب: <code>' + m.group + '</code>\n'
    + R + '👤 العميل: ' + esc(m.customer_name) + '\n'
    + R + '📱 الرقم: ' + m.customer_id + '\n'
    + R + (m.type === 'image' ? '🖼️ النوع: روشتة (صورة)' : (m.type === 'audio' ? '🎙️ النوع: رسالة صوتية' : '💬 النوع: رسالة نصية'))
    + '</blockquote>\n'
    + (m.type === 'audio' && m.transcript ? '<blockquote>' + R + '🎙️ <b>اللي اتسمع:</b>\n' + R + esc(m.transcript) + '</blockquote>\n' : '')
    + '<blockquote>' + R + '💊 <b>الأدوية المطلوبة</b>\n\n' + items + unclear + '</blockquote>\n'
    + '<blockquote>' + R + '💰 <b>الإجمالي: ' + total + ' جنيه</b>\n'
    + R + '📌 سبب المراجعة: ' + why + '</blockquote>\n\n'
    + R + '👇 <b>اختار قرارك</b>';
})() }}

parameters.jsCode:
const cb = $input.first().json.callback_query;
const parts = cb.data.split(':');   // ph : approve : R-YYMMDD-XXXX : 2010XXXXXXXX

return [{
  json: {
    action: parts[1],
    group: parts[2],
    customer_id: parts[3],
    callback_query_id: cb.id,
    chat_id: cb.message.chat.id,
    message_id: cb.message.message_id,
    pharmacist: cb.from.first_name,
    original: cb.message.text
  }
}];

// ===== Apply Decision: تفاصيل القرار + المخزون + الحجز في item واحد =====
const EXPIRY_MIN = 120;

const d = $('Parse Decision').first().json;
const rows = $('Find Pending Lines').all().map(i => i.json)
  .filter(r => r.res_id && String(r.res_id).startsWith(d.group + '-') && r.status === 'pending_pharmacist');

const ok = d.action === 'approve';
const out = {
  ...d, ok: ok, already: false, blocked: false, short: '', toast: '',
  customer_name: '', wa_phone_id: '', expires_at: '', total: 0, lines: [], stock: []
};

// القرار اتاخد قبل كده
if (!rows.length) {
  out.already = true;
  out.toast = 'اتقرر قبل كده';
  return [{ json: out }];
}

out.customer_name = rows[0].customer_name;
out.wa_phone_id = rows[0].wa_phone_id;

// المخزون الحالي من الكتالوج
const cat = {};
for (const i of $('Read Catalog (Decision)').all()) {
  if (i.json.sku) cat[i.json.sku] = { name: i.json.name, stock: Number(i.json.stock) || 0 };
}

// الكمية المطلوبة لكل sku
const need = {};
for (const r of rows) if (r.sku) need[r.sku] = (need[r.sku] || 0) + Number(r.qty || 0);

// تفاصيل المخزون
const short = [];
for (const sku of Object.keys(need)) {
  const before = cat[sku] ? cat[sku].stock : 0;
  const enough = before >= need[sku];
  if (ok && !enough) short.push(sku);
  out.stock.push({ sku: sku, name: cat[sku] ? cat[sku].name : '', need: need[sku], before: before, enough: enough, deduct: 0, after: before });
}

// منع الموافقة لو المخزون لا يكفي
if (short.length) {
  out.blocked = true;
  out.short = short.join(', ');
  out.toast = 'المخزون لا يكفي';
  return [{ json: out }];
}

const exp = ok ? $now.setZone('Africa/Cairo').plus({ minutes: EXPIRY_MIN }).toFormat('yyyy-MM-dd HH:mm') : '';
out.expires_at = exp;

// تفاصيل الحجز
out.lines = rows.map(r => {
  let status = 'rejected';
  if (ok) status = r.sku ? 'reserved' : 'not_available';
  return {
    res_id: r.res_id, sku: r.sku, name: r.name, qty: Number(r.qty),
    total_egp: Number(r.total_egp) || 0, status: status,
    expires_at: status === 'reserved' ? exp : '', note: r.note || ''
  };
});

// الخصم عند الموافقة بس
if (ok) for (const s of out.stock) { s.deduct = s.need; s.after = s.before - s.need; }

out.total = out.lines.filter(l => l.status === 'reserved').reduce((t, l) => t + l.total_egp, 0);
out.toast = ok ? 'Approved' : 'Rejected';
return [{ json: out }];

// ===== Line Updates =====
const a = $('Apply Decision').first().json;
if (a.already || a.blocked) return [];
return a.lines.map(l => ({ json: { res_id: l.res_id, status: l.status, expires_at: l.expires_at, pharmacist: a.pharmacist } }));

// ===== Stock Rows =====
const a = $('Apply Decision').first().json;
return a.stock.filter(s => s.deduct > 0).map(s => ({ json: { sku: s.sku, stock: s.after } }));

