    by = '⚠️ Not approved · ' + esc(a.pharmacist);
  }
  if (a.already) {
    head = 'ℹ️ <b>الطلب اتقرر قبل كده</b>';
    by = 'ℹ️ Already decided';
  }

  const items = lines.length
    ? '\n\n' + R + '💊 <b>الأدوية:</b>\n' + lines.map(l => R + '• ' + esc(l.name) + ' × ' + l.qty + (l.status === 'not_available' ? ' ❌ غير متوفر' : ' — ' + l.total_egp + ' جنيه')).join('\n')
    : '';
  const sum = lines.filter(l => l.status !== 'not_available').reduce((t, l) => t + l.total_egp, 0);
  const total = lines.length ? '\n\n' + R + '💰 <b>الإجمالي:</b> ' + sum + ' جنيه' : '';
  const who = a.customer_name ? '\n' + R + '👤 العميل: ' + esc(a.customer_name) + '\n' + R + '📱 ' + a.customer_id : '';

  return R + head + '\n' + R + '🧾 <code>' + a.group + '</code>' + who + items + total
        + '\n\n' + R + '🕒 ' + time + ' · ' + by;
})() }}

